    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == obj]
    cs = set(cells)
    seen = set(); comps = []
    for cell in cells:
        if cell in seen:
            continue
        stack = [cell]; comp = set()
        while stack:
            r, c = stack.pop()
            if (r, c) in seen:
                continue
            seen.add((r, c)); comp.add((r, c))
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    if dr == 0 and dc == 0:
                        continue
                    p = (r + dr, c + dc)
                    if p in cs and p not in seen:
                        stack.append(p)
        comps.append(comp)
    comps.sort(key=len, reverse=True)
    comp = comps[0]
    r0 = min(r for r, c in comp); c0 = min(c for r, c in comp)
    offs = sorted((r - r0, c - c0) for r, c in comp)

    def all_obj(a, b):
        return all(0 <= a + dr < h and 0 <= b + dc < w and grid[a + dr][b + dc] == obj
                   for dr, dc in offs)

    protected = set()
    for a in range(h):
        for b in range(w):
            if all_obj(a, b):
                for dr, dc in offs:
                    protected.add((a + dr, b + dc))

    g = [row[:] for row in grid]
    for a in range(h):
        for b in range(w):
            pts = [(a + dr, b + dc) for dr, dc in offs]
            if any(not (0 <= r < h and 0 <= c < w) for r, c in pts):
                continue
            vals = [grid[r][c] for r, c in pts]
            if any(v not in (0, obj) for v in vals):
                continue
            if all(v == obj for v in vals):
                continue
            if any(grid[r][c] == obj and (r, c) in protected for r, c in pts):
                continue
            for (r, c), v in zip(pts, vals):
                if v == 0:
                    g[r][c] = obj
    return g

