    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    by_color = defaultdict(list)
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                by_color[grid[r][c]].append((r, c))
    for color, cells in by_color.items():
        for keyfn in (lambda r, c: r - c, lambda r, c: r + c):
            groups = defaultdict(list)
            for r, c in cells:
                groups[keyfn(r, c)].append((r, c))
            for key, grp in groups.items():
                if len(grp) < 2:
                    continue
                grp.sort()
                (r0, c0), (r1, c1) = grp[0], grp[1]
                dr = (r1 > r0) - (r1 < r0)
                dc = (c1 > c0) - (c1 < c0)
                r, c = grp[-1][0] + dr, grp[-1][1] + dc
                while 0 <= r < H and 0 <= c < W and out[r][c] == bg:
                    out[r][c] = color
                    r += dr; c += dc
                r, c = grp[0][0] - dr, grp[0][1] - dc
                while 0 <= r < H and 0 <= c < W and out[r][c] == bg:
                    out[r][c] = color
                    r -= dr; c -= dc
    return out

def transform(grid):
    from collections import Counter, defaultdict
    H = len(grid); W = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    out = [row[:] for row in grid]
    colored = {}
    for r in range(H):
        for c in range(W):
            if grid[r][c] != bg:
                colored[(r, c)] = grid[r][c]

    def adjacent_foreign(r, c, color):
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                v = colored.get((r + dr, c + dc))
                if v is not None and v != color:
                    return True
        return False

    by_color = defaultdict(list)
    for (r, c), v in colored.items():
        by_color[v].append((r, c))
    for color, cells in by_color.items():
        for keyfn in (lambda r, c: r - c, lambda r, c: r + c):
            groups = defaultdict(list)
            for r, c in cells:
                groups[keyfn(r, c)].append((r, c))
            for key, grp in groups.items():
                if len(grp) < 2:
                    continue
                grp.sort()
                (r0, c0), (r1, c1) = grp[0], grp[-1]
                dr = (r1 > r0) - (r1 < r0)
                dc = (c1 > c0) - (c1 < c0)
                if dr == 0 and dc == 0:
                    continue
                # shoot only from a free (non-anchored) end, away from cluster
                ends = []
                if not adjacent_foreign(r0, c0, color):
                    ends.append((r0 - dr, c0 - dc, -dr, -dc))
                if not adjacent_foreign(r1, c1, color):
                    ends.append((r1 + dr, c1 + dc, dr, dc))
                for r, c, ddr, ddc in ends:
                    while 0 <= r < H and 0 <= c < W:
                        if (r, c) in colored or adjacent_foreign(r, c, color):
                            break
                        out[r][c] = color
                        r += ddr; c += ddc
    return out

