def transform(grid):
    from collections import Counter
    R, W = len(grid), len(grid[0])
    c = Counter(v for row in grid for v in row)
    accent = min(c, key=c.get)
    has = [any(v == accent for v in row) for row in grid]
    bands = []
    i = 0
    while i < R:
        if has[i]:
            j = i
            while j + 1 < R and has[j + 1]:
                j += 1
            bands.append((i, j))
            i = j + 1
        else:
            i += 1
    out = [list(row) for row in grid]

    def cols_of(r):
        return [k for k, v in enumerate(grid[r]) if v == accent]

    def prefix_row(r):
        cs = cols_of(r)
        return cs[0] == 0 and all(cs[k + 1] == cs[k] + 1 for k in range(len(cs) - 1))

    if all(j0 - i0 == 0 for i0, j0 in bands):
        for i0, j0 in bands:
            r = i0
            if prefix_row(r):
                last = cols_of(r)[-1]
                for j in range(last + 1, W):
                    out[r][j] = 1
        return out

    def src_ext(srow, sc):
        if 0 <= sc < W:
            return srow[sc]
        return srow[W - 2 + (sc - W) % 2]

    for bi in range(1, len(bands)):
        i0, j0 = bands[bi]
        pi, pj = bands[bi - 1]
        for idx, r in enumerate(range(i0, j0 + 1)):
            src = pi + idx
            if src > pj:
                src = pj
            srow = grid[src]
            last = cols_of(r)[-1]
            for j in range(last + 1, W):
                if src_ext(srow, j + 1) == accent:
                    out[r][j] = 1
    return out

def transform(grid):
    from collections import Counter
    R = len(grid); W = len(grid[0])
    out = [list(row) for row in grid]
    cnt = Counter(v for row in grid for v in row)
    if len(cnt) < 2:
        return out
    accent = min(cnt, key=lambda c: (cnt[c], c))
    A = [[c for c, v in enumerate(row) if v == accent] for row in grid]
    arows = [r for r in range(R) if A[r]]
    if not arows:
        return out
    full = [r for r in arows if len(A[r]) == W]
    if full:
        for r in arows:
            if len(A[r]) < W:
                for c in range(W):
                    if grid[r][c] != accent:
                        out[r][c] = 1
        return out
    bands = []
    i = 0
    while i < R:
        if A[i]:
            j = i
            while j + 1 < R and A[j + 1]:
                j += 1
            bands.append((i, j))
            i = j + 1
        else:
            i += 1
    for (i1, j1), (i2, j2) in zip(bands, bands[1:]):
        n = min(j1 - i1, j2 - i2) + 1
        A1 = [set(A[i1 + k]) for k in range(n)]
        A2 = [set(A[i2 + k]) for k in range(n)]
        best = None
        for s in range(-(W - 1), W):
            sc = 0
            for k in range(n):
                sh = {a + s for a in A1[k]}
                sc += len(A2[k] & sh)
            if best is None or sc > best[0] or (sc == best[0] and abs(s) < abs(best[1])):
                best = (sc, s)
        s = best[1]
        c1 = sum(len(x) for x in A1)
        c2 = sum(len(x) for x in A2)
        if c2 <= c1:
            for k in range(n):
                for c in range(W):
                    if grid[i2 + k][c] != accent and (c - s) in A1[k]:
                        out[i2 + k][c] = 1
        else:
            for k in range(n):
                for c in range(W):
                    if grid[i1 + k][c] != accent and (c + s) in A2[k]:
                        out[i1 + k][c] = 1
    return out

def transform(grid):
    h = len(grid)
    w = len(grid[0])
    # find separator: a fully constant row or column whose value differs from most cells
    sep_row = None
    sep_col = None
    for r in range(h):
        vals = {grid[r][c] for c in range(w)}
        if len(vals) == 1:
            sep_row = r
            break
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            sep_col = c
            break
    if sep_row is not None:
        top = grid[:sep_row]
        bot = grid[sep_row + 1:]
        n = min(len(top), len(bot))
        m = w
        A = [[top[i][j] for j in range(m)] for i in range(n)]
        B = [[bot[i][j] for j in range(m)] for i in range(n)]
    elif sep_col is not None:
        left = [row[:sep_col] for row in grid]
        right = [row[sep_col + 1:] for row in grid]
        n = h
        m = min(len(left[0]), len(right[0]))
        A = [[left[i][j] for j in range(m)] for i in range(n)]
        B = [[right[i][j] for j in range(m)] for i in range(n)]
    else:
        return grid
    setA = set()
    setB = set()
    for row in A:
        setA |= set(row)
    for row in B:
        setB |= set(row)
    common = setA & setB
    accent = list(common)[0] if len(common) == 1 else (sorted(common)[0] if common else 0)
    out = []
    for i in range(n):
        row = []
        for j in range(m):
            if A[i][j] == accent and B[i][j] == accent:
                row.append(3)
            else:
                row.append(accent)
        out.append(row)
    return out

def transform(grid):
    h = len(grid)
    w = len(grid[0])
    sep = None
    for c in range(w):
        col = {grid[r][c] for r in range(h)}
        if len(col) == 1:
            v = col.pop()
            others = {grid[r][cc] for r in range(h) for cc in range(w) if cc != c}
            if v not in others:
                sep = ('c', c)
                break
    if sep is None:
        for r in range(h):
            row = set(grid[r])
            if len(row) == 1:
                v = row.pop()
                others = {grid[rr][cc] for rr in range(h) if rr != r for cc in range(w)}
                if v not in others:
                    sep = ('r', r)
                    break
    if sep is None:
        return grid
    if sep[0] == 'c':
        c = sep[1]
        A = [row[:c] for row in grid]
        B = [row[c + 1:] for row in grid]
        n, m = h, min(c, w - c - 1)
    else:
        r = sep[1]
        A = grid[:r]
        B = grid[r + 1:]
        n, m = min(r, h - r - 1), w
    setA = {v for row in A for v in row}
    setB = {v for row in B for v in row}
    common = setA & setB
    accent = sorted(common)[0] if common else 0
    out = []
    for i in range(n):
        out.append([3 if (A[i][j] == accent and B[i][j] == accent) else accent
                    for j in range(m)])
    return out

def transform(grid):
    from collections import Counter
    R, C = len(grid), len(grid[0])
    div_rows = {r for r in range(R) if len(set(grid[r])) == 1}
    div_cols = {c for c in range(C) if len({grid[r][c] for r in range(R)}) == 1}
    divcolor = next(iter({grid[r][c] for r in div_rows for c in (0,)})) if div_rows else None

    bands, start = [], None
    for r in range(R):
        if r in div_rows:
            if start is not None: bands.append((start, r - 1)); start = None
        elif start is None:
            start = r
    if start is not None: bands.append((start, R - 1))

    colbands, start = [], None
    for c in range(C):
        if c in div_cols:
            if start is not None: colbands.append((start, c - 1)); start = None
        elif start is None:
            start = c
    if start is not None: colbands.append((start, C - 1))

    cnt = Counter(grid[r][c] for r in range(R) for c in range(C)
                  if r not in div_rows and c not in div_cols)
    majority = cnt.most_common(1)[0][0]

    out = []
    for r0, r1 in bands:
        row = []
        for c0, c1 in colbands:
            n = sum(1 for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                    if grid[r][c] != majority and grid[r][c] != divcolor)
            row.append(1 if n == 2 else majority)
        out.append(row)
    return out

